insert into public.trips select (jsonb_populate_record(null::public.trips,to_jsonb(t)||jsonb_build_object('id','f2000000-0000-4000-8000-000000000003','trip_no','QA-TEST/261117/PROMPT20','status','loaded','created_at',now(),'updated_at',now(),'loaded_at',now(),'gate_out_at',null,'gate_out_by',null,'gate_in_at',null,'gate_in_by',null,'driver_started_at',null,'ended_at',null,'settled_at',null,'settled_by',null,'returns_received_at',null,'start_odometer',null,'end_odometer',null,'start_odometer_photo_url',null,'end_odometer_photo_url',null,'start_selfie_url',null,'cash_expected',0,'cash_received',null))).* from public.trips t where id='f1800000-0000-4000-8000-000000000003';
insert into public.orders select (jsonb_populate_record(null::public.orders,to_jsonb(o)||jsonb_build_object('id',v.id,'order_no',v.no,'status','approved','created_at',now(),'updated_at',now(),'payment_method',v.mode,'payment_mode','cod','amount_paid',0,'notes','QA-TEST Prompt20 cheque/bank saves'))).* from public.orders o cross join (values ('f2000000-0000-4000-8000-000000000001','QA-TEST-PROMPT20-CHEQUE','cheque'),('f2000000-0000-4000-8000-000000000002','QA-TEST-PROMPT20-BANK','bank')) v(id,no,mode) where o.id='f1800000-0000-4000-8000-000000000001';
insert into public.order_lines select (jsonb_populate_record(null::public.order_lines,to_jsonb(l)||jsonb_build_object('id',gen_random_uuid(),'order_id',o.id))).* from public.order_lines l cross join public.orders o where l.order_id='f1800000-0000-4000-8000-000000000001' and o.order_no in ('QA-TEST-PROMPT20-CHEQUE','QA-TEST-PROMPT20-BANK');
